"""Read-only proposal builder for oversized autogenerated skills.

It never calls SkillManage and never writes to the source package.  The output is
an inspectable body/reference split plus a manifest that can reconstruct bytes.
"""
from __future__ import annotations
import argparse, hashlib, json
from pathlib import Path

DEFAULT_SOURCE = Path.home()/".swarm/skills/autogen/swarm-stack-engineering/SKILL.md"
# These are deliberately explicit: only the duplicated budget/UI procedure is
# eligible.  Facts, safety constraints, and the final canonical procedure stay.
MOVE_HEADINGS = (
    "## Pi-Swarm UI budget integration",
    "## Autogenerated-skill activation and budget enforcement",
    "## Curator consolidation: autogen activation and budget enforcement",
    "## Curator consolidation: Pi-Swarm UI runtime budgets",
    "## Curator additions: autogen budget enforcement and Pi UI integration",
    "## Runtime budget visibility and autogen activation boundaries",
    "## Autogenerated activation and budget enforcement",
    "## Pi-Swarm UI runtime-budget integration",
)
KEEP_HEADINGS = ("## Runtime budget enforcement and UI exposure",)
LOAD_POINTER = "\nFor budget accounting, skill activation, or runtime-budget UI work, load [the detailed edge-case checklist](references/budget-ui-history.md) before implementation. It preserves invocation/idempotency, concurrency, refund, lifecycle protection, accessibility, and UI-state obligations.\n"

class SourceChanged(ValueError): pass

def sha(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()

def split_sections(text: str):
    lines = text.splitlines(keepends=True)
    starts = [i for i,l in enumerate(lines) if l.startswith("## ")]
    out=[]
    for n,start in enumerate(starts):
        end = starts[n+1] if n+1<len(starts) else len(lines)
        out.append((lines[start].rstrip("\r\n"), start, end, "".join(lines[start:end])))
    return out

def build(source: Path, out: Path):
    original = source.read_bytes(); original_hash=sha(original)
    text=original.decode("utf-8")
    sections=split_sections(text)
    chosen=[x for x in sections if x[0] in MOVE_HEADINGS]
    if len(chosen)!=len(MOVE_HEADINGS):
        raise ValueError("source missing one or more explicitly approved headings")
    if not all(any(x[0]==h for x in sections) for h in KEEP_HEADINGS):
        raise ValueError("canonical retained section missing")
    # Replace only complete approved sections; all other bytes are retained.
    moved={x[1]:x[3] for x in chosen}
    lines=text.splitlines(keepends=True); body=[]; spans=[]; cursor=0
    for start,end in sorted((x[1],x[2]) for x in chosen):
        if cursor<start: body.append("".join(lines[cursor:start])); spans.append({"kind":"retained","start":cursor,"end":start})
        body.append("\n<!-- Detailed historical budget/UI procedures moved to references/budget-ui-history.md. -->\n")
        spans.append({"kind":"moved","start":start,"end":end})
        cursor=end
    if cursor<len(lines): body.append("".join(lines[cursor:])); spans.append({"kind":"retained","start":cursor,"end":len(lines)})
    body_text="".join(body).replace(KEEP_HEADINGS[0]+"\n",KEEP_HEADINGS[0]+"\n"+LOAD_POINTER,1)
    moved_text="".join(moved[k] for k in sorted(moved))
    out.mkdir(parents=True,exist_ok=True)
    (out/'preview-body.md').write_bytes(body_text.encode())
    (out/'preview-references-budget-ui-history.md').write_bytes(moved_text.encode())
    manifest={"source":str(source),"source_sha256":original_hash,"source_bytes":len(original),"body_bytes":len(body_text.encode()),"reference_bytes":len(moved_text.encode()),"spans":spans,"reference":"references/budget-ui-history.md","retained_canonical_headings":list(KEEP_HEADINGS),"moved_headings":list(MOVE_HEADINGS),"mutations":0}
    (out/'preview-manifest.json').write_text(json.dumps(manifest,indent=2)+"\n")
    facts=[
      {"fact":"Runtime budget UI must project authoritative execution state","repo_mapping":"packages/context/autogenskills/src/index.ts (autogen lifecycle); inspect Pi-Swarm runtime/TUI package before promotion","status":"candidate; not written"},
      {"fact":"SkillManage lifecycle mutations require source/package integrity and relative-link preservation","repo_mapping":"packages/context/autogenskills/src/index.ts and package tests","status":"candidate; not written"},
    ]
    report=(f"source_sha256: {original_hash}\nsource_bytes: {len(original)}\n"
            f"proposed_body_bytes: {len(body_text.encode())}\nproposed_reference_bytes: {len(moved_text.encode())}\n"
            f"reduction_bytes: {len(original)-len(body_text.encode())}\n\n"
            "Affected headings (moved byte-for-byte):\n"+"\n".join("- "+h for h in MOVE_HEADINGS)+"\n\n"
            "Retained canonical heading:\n- "+KEEP_HEADINGS[0]+"\n\n"
            "Candidate project facts (not written):\n"+"\n".join(f"- {x['fact']} — mapping: {x['repo_mapping']}" for x in facts)+"\n\n"
            "No SkillManage call; source package was not modified.\n")
    (out/'preview-report.txt').write_text(report)
    return manifest

def reconstruct(source: bytes, body: bytes, reference: bytes, manifest: dict) -> bytes:
    if sha(source)!=manifest["source_sha256"]: raise SourceChanged("source hash does not match proposal")
    lines=source.decode().splitlines(keepends=True); refs=reference.decode(); pos=0; chunks=[]
    expected_body=[]; expected_reference=[]
    marker="\n<!-- Detailed historical budget/UI procedures moved to references/budget-ui-history.md. -->\n"
    for span in manifest["spans"]:
        original_piece="".join(lines[span["start"]:span["end"]])
        if span["kind"]=="retained": expected_body.append(original_piece)
        else: expected_body.append(marker); expected_reference.append(original_piece)
    if body != "".join(expected_body).replace(KEEP_HEADINGS[0]+"\n",KEEP_HEADINGS[0]+"\n"+LOAD_POINTER,1).encode(): raise SourceChanged("proposed body differs from allowed transformation")
    if reference != "".join(expected_reference).encode(): raise SourceChanged("reference bytes differ from original moved sections")
    for s in manifest["spans"]:
        if s["kind"]=="retained": chunks.append("".join(lines[s["start"]:s["end"]]))
        else:
            end=pos+len("".join(lines[s["start"]:s["end"]])); chunks.append(refs[pos:end]); pos=end
    return "".join(chunks).encode()

def main():
    ap=argparse.ArgumentParser(); ap.add_argument("--source",type=Path,default=DEFAULT_SOURCE); ap.add_argument("--out",type=Path,required=True); a=ap.parse_args(); build(a.source,a.out)
if __name__=="__main__": main()
